mapper.sql:
rta_match_in_season AS (
	SELECT m.replay_id AS rid, m.played_at AS date_add, m.winner_wizard_id, m.battle_type
	FROM public.rta_match m
	WHERE 1 = 1

		AND m.played_at >= #{seasonStart}
		AND m.played_at < #{seasonEnd}

)

sql.if:
AND EXISTS (
	SELECT 1
	FROM public.rta_match_participant pp
	WHERE pp.replay_id = m.replay_id
	  AND pp.rating_id IN (
		SELECT rg.rating_id
		FROM public.rta_rating_grade rg
		WHERE rg.tier_key = #{tierKey}
	  )
)
